insert into public.cpl_memory (slug, title, kind, summary, detail, plain, tags, affects, source, author, event_date, status, verified_by, verified_at)
values
('sam-sheet29-rulings-2026-10-04', 'Sam''s rulings on open-asks sheet 29 (all five cards, his own calls)', 'decision', 'Sam, 2026-10-04 11:54-12:00Z, each his own call: 1 later (two memory receipts); 2 guard lifted, run it (six catalog addresses); 3 note Miramar''s mapper refusal in the college''s record, no ask for access, make the agent aware and keep looking for solutions or workarounds; 4 yes, Sierra may say required and give a total for checked records; 5 go on the addenda table.', 'Read from the sheet''s reply store (artifact FhxQ5HXM1EBffhS5ce3Tj7, collection replies; done through 5, ruled 5, as_proposed 0). Card 3 carried no chip, a Follow up flag and the note, verbatim: "Note this in the record for the college. Rather than ask permission, we will make the agent aware of the limitation and to continue to look for solutions or workarounds." S326 carried out 2, 3 and 5 the same day; 4 is built next behind the A/B preview and a smoke; 1 rides open-asks sheet 30 (SKczLvwB5BxQMXNfJRdyD3) with the addenda table''s privilege close.', 'Sam answered all five questions on decision sheet 29.', array['program-requirements','decision-sheet','sierra','addenda']::text[], array['docs/reference/lanes/program-requirements-harvest.md']::text[], 'open-asks sheet 29 replies, read 2026-10-04 by S326', 'SkyAddendum-s326', '2026-10-04', 'verified', 'Sam', now()),
('sam-s325-program-requirements-tab-calls-2026-10-04', 'Sam''s S325 calls: no Governance pass for the harvest tab (beta draft), Sierra in the tab, addenda in the schema', 'decision', 'Sam, 2026-10-04 (S325): "No need for governance at this point. Everything is public record and we can mark the tab and contents as beta draft." "Integrate Sierra in the tab design"; one Ask Sierra link; she needs the catalog and pathway data and the agentic procedures. "later we will be integrating all this in SkyView." Addenda: "track this in our schema and have our agents aware."', 'Also S325: "Can''t find sheet 28... add the sheet link next to a presence to it in chat" (now CLAUDE.md, Link every sheet you name). Sierra, verbatim (11:33Z): "Most important with her is that she has access to the catalog and pathway data we are assembling but also the logic and agentic procedures we''re iterating." Vault braindump: CPLBrain/03-professional/braindumps/braindump-2026-10-04-1115-program-requirements-tab-public-record.md. Recorded by S326 because S325 ended on an emergency checkpoint that skipped its memory rows.', 'Sam ruled the program requirements tab needs no Governance pass and carries Sierra.', array['program-requirements','sierra','governance','addenda']::text[], array['docs/reference/lanes/program-requirements-harvest.md']::text[], 'Sam in session S325, 2026-10-04, per docs/session_326_handoff.md', 'SkyAddendum-s326', '2026-10-04', 'verified', 'Sam', now()),
('program-source-addenda-table-live-2026-10-04', 'The catalog addenda table is live and the census writes it', 'milestone', 'program_source_addenda is live (S326, Sam''s go): one row per (college, url), a status from listed to applied, history by trigger, public read. The census writes it after the registry through program_source_addenda_apply(), marking an addendum gone only after a complete read (homepage and catalog page both answered). Empty until the next apply; the 2026-10-04 Sunday schedule did not fire.', 'Migrations program_source_addenda_create_2026_10_04 and program_source_addenda_return_keeps_read_2026_10_04. The write function is security invoker: RLS (one SELECT policy) keeps anon and authenticated out of every write. The default-privilege close is kb/receipts/program_source_addenda_close_2026-10-04_s326.sql, for Sam to paste (open-asks sheet 30). Logic checked live in two blocks that end by raising, so nothing persisted: new 2, seen again 1, a partial read marks nothing gone, a complete read marks one gone, a returning addendum comes back read if read_at is set, else listed.', 'The database now tracks catalog addenda, and the weekly catalog reader fills it.', array['program-requirements','addenda','census','registry']::text[], array['kb/supabase_program_source_addenda.sql','kb/_program_source_census.py']::text[], 'S326 migrations and live read-backs, 2026-10-04', 'SkyAddendum-s326', '2026-10-04', 'proposed', null, null),
('sequence-access-on-the-registry-2026-10-04', 'The registry records where each college''s course sequence can be read; the reader skips a refusing host', 'fact', 'program_source_registry carries sequence_host, sequence_access (open, refused, unreached, not_read), sequence_note and sequence_checked_run, which the census never writes. Filed for 25 colleges on 2026-10-04: 18 refused (Miramar and the probe''s 17 mapper hosts), 5 not read, 1 open (Irvine Valley), 1 unreached (Santa Monica). The sequence reader never requests a refused host.', 'Sam''s sheet 29 card 3. Receipt kb/receipts/program_source_registry_sequence_access_2026-10-04_s326.sql (migration program_source_registry_sequence_access_2026_10_04); the history trigger names sequence_checked_run. kb/_program_sequence_ppm.py reads the four columns, follows the college''s own links to a map, pathway, roadmap or sequence (alt_link), and its probe asks each recorded host''s front page once a run, printing OPENED: file it when one answers. The reader keeps the census user agent that names the CPL Initiative, so a workaround means another public source, never the refused host under another name.', 'Each college''s record now says whether its program maps can be read, and the reader respects it.', array['program-requirements','sequence','registry','ppm']::text[], array['kb/_program_sequence_ppm.py','kb/supabase_program_source_registry.sql']::text[], 'probe run 37198225537 and sequence run 37197332656, filed by S326', 'SkyAddendum-s326', '2026-10-04', 'proposed', null, null),
('invoker-write-function-lets-a-table-go-live-before-its-close-2026-10-04', 'A security-invoker write function lets a new table go live while its privilege close waits on a person', 'procedure', 'The Supabase connector holds any statement naming a destructive SQL keyword for a confirmation a remote session cannot answer, so a privilege close cannot ride a table''s create. Make the write function security invoker, enable RLS with only a SELECT policy, and grant service_role explicitly: the create-only part applies at once, no public role can write, and a person runs the close.', 'Measured S326: the full addenda file timed out at 60 s and wrote nothing; the create-only part applied in about a second. service_role holds BYPASSRLS. A security definer function would be callable by PUBLIC until the close lands, so it must wait for the close. Extends mcp-apply-migration-destructive-confirm-times-out-2026-10-02.', 'How to ship a new table safely when the database tool stalls on permission changes.', array['supabase','methodology','rule-10']::text[], array['kb/supabase_program_source_addenda.sql']::text[], 'S326, migration program_source_addenda_create_2026_10_04', 'SkyAddendum-s326', '2026-10-04', 'proposed', null, null),
('raise-at-the-end-tests-a-write-function-live-2026-10-04', 'A block that raises at its end tests a write function against the live schema and keeps nothing', 'procedure', 'To check a new write function on the live database without leaving rows, run it in an anonymous block through the migration path, read the results into the exception text, and end with raise exception. The whole transaction rolls back, no migration is recorded, and the error message carries the results.', 'S326 checked program_source_addenda_apply() this way twice (four calls each), then read back 0 rows, 0 history rows and no migration named for the check. The block runs as the owner, so it tests logic, not grants; read grants separately with has_table_privilege and has_function_privilege. Sequence values it consumed are not returned.', 'A safe way to test a database function for real without changing any data.', array['supabase','methodology','verification']::text[], '{}'::text[], 'S326 live checks, 2026-10-04', 'SkyAddendum-s326', '2026-10-04', 'proposed', null, null),
('census-sunday-apply-did-not-fire-2026-10-04', 'The census weekly apply did not fire on its first Sunday', 'fact', 'program-source-census.yml is scheduled for Sundays 10:29 UTC, and on 2026-10-04 no scheduled run appears; the registry''s last census run is census-20261003T221526Z. The addenda table stays empty until a run applies: the next Sunday (2026-10-11) or a hand dispatch on main with mode apply.', 'Read through the GitHub connector at about 13:45Z 2026-10-04: 15 runs, all push or workflow_dispatch. GitHub drops or delays scheduled runs under load; if 2026-10-11 also shows none, check the workflow is enabled and the cron line is on main.', 'The weekly catalog check skipped its first scheduled run.', array['program-requirements','census','workflow']::text[], array['.github/workflows/program-source-census.yml']::text[], 'GitHub Actions run list, 2026-10-04', 'SkyAddendum-s326', '2026-10-04', 'proposed', null, null)
